13	/**
14	 * The port's HTTP implementation: it turns a provider's vocabulary into this
15	 * application's, and its bad days into one failure the caller can act on.
16	 *
17	 * <p>Spring Framework 7 has no {@code @Recover}, and when the retry budget runs out it
18	 * rethrows the last attempt's exception unchanged rather than a wrapper announcing
19	 * exhaustion. So there is nothing to distinguish "the provider returned {@code 503}" from
20	 * "the provider returned {@code 503} three times" at the point it is caught — which is
21	 * exactly why the retried call is a bean of its own. Everything reaching the {@code catch}
22	 * below has already been retried as far as it will be, and the attempt count comes from
23	 * the same setting the annotation counted with.
24	 */
25	@Service
26	class HttpExchangeRateProvider implements ExchangeRateProvider {
27	
28		private static final Logger log = LoggerFactory.getLogger(HttpExchangeRateProvider.class);
29	
30		private final RetriedQuotes quotes;
31	
32		private final ExchangeRateSettings settings;
33	
34		private final Clock clock;
35	
36		HttpExchangeRateProvider(RetriedQuotes quotes, ExchangeRateSettings settings, Clock clock) {
37			this.quotes = quotes;
38			this.settings = settings;
39			this.clock = clock;
40		}
41	
42		@Override
43		public ExchangeRate exchangeRateFor(Currency base, Currency quote) {
44			ProviderQuote answer;
45			try {
46				answer = quotes.forPair(base, quote);
47			}
48			catch (HttpServerErrorException | ResourceAccessException exhausted) {
49				log.warn("The exchange rate provider did not answer for {}/{} in {} attempts",
50						base, quote, settings.attemptsPerRequest(), exhausted);
51				throw new ExchangeRateUnavailableException(base, quote, settings.attemptsPerRequest(), exhausted);
52			}
53			catch (RestClientException refused) {
54				throw new IllegalStateException(
55						"the exchange rate provider refused a %s/%s request".formatted(base, quote), refused);
56			}
57			return asExchangeRate(base, quote, answer);
58		}
59	
60		/**
61		 * Checks the provider's answer against the question before believing it.
62		 *
63		 * <p>A quote for the wrong pair is the one provider defect that would otherwise be
64		 * silent: the number is well-formed, the response is a {@code 200}, and the transfer
65		 * settles at a rate for two currencies nobody asked about. So the echo is compared
66		 * rather than discarded, and a mismatch is a defect above this client — unchecked, and
67		 * nothing catches it — for the same reason ticket 07 refuses a rate of zero.
68		 */
69		private ExchangeRate asExchangeRate(Currency base, Currency quote, ProviderQuote answer) {
70			if (answer == null) {
71				throw new IllegalStateException(
72						"the exchange rate provider answered a %s/%s request with no body".formatted(base, quote));
73			}
74			if (!base.name().equals(answer.base()) || !quote.name().equals(answer.quote())) {
75				throw new IllegalStateException("asked the exchange rate provider for %s/%s and it quoted %s/%s"
76						.formatted(base, quote, answer.base(), answer.quote()));
77			}
78			return new ExchangeRate(base, quote, answer.rate(), clock.instant());
79		}
