package hu.bankmonitor.payments.fx;

import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.task.VirtualThreadTaskExecutor;
import org.springframework.http.client.ClientHttpRequestFactory;
import org.springframework.http.client.JdkClientHttpRequestFactory;
import org.springframework.resilience.annotation.EnableResilientMethods;
import org.springframework.web.client.RestClient;

import java.net.http.HttpClient;

/**
 * The one client in this application that talks to somebody else, and the two settings
 * that keep it from talking forever.
 *
 * <p>{@code @EnableResilientMethods} is application-wide — it registers a bean
 * post-processor, not a slice-local one — but it is declared here rather than in the root
 * package because the only retryable method in the system is a few lines away, and a
 * second slice wanting retry should find the annotation by finding the code that already
 * uses it. Spring Boot does not auto-configure it; without this line {@code @Retryable}
 * is an annotation nothing reads, and the first attempt is the only attempt, silently.
 */
@Configuration
@EnableResilientMethods
@EnableConfigurationProperties(ExchangeRateSettings.class)
class ExchangeRateConfiguration {

	@Bean
	RestClient exchangeRateClient(ExchangeRateSettings settings) {
		return RestClient.builder()
				.baseUrl(settings.baseUrl().toString())
				.requestFactory(boundedByTimeouts(settings))
				.build();
	}

	/**
	 * Both timeouts, on the JDK's own HTTP client.
	 *
	 * <p>Without them "the provider is slow" has no upper bound, and §27's failure mode
	 * arrives: a request parks indefinitely while holding an in-progress Idempotency Key,
	 * so an unreliable third party becomes a Transfer that can never be retried.
	 *
	 * <p>The connect timeout belongs to the client and the read timeout to the request
	 * factory, because the JDK client has no read timeout of its own — Spring's factory
	 * implements it as a watchdog over the whole response. Spring Boot's
	 * {@code ClientHttpRequestFactoryBuilder} performs exactly these two calls, and is not
	 * used here only because it lives in an artifact this project does not otherwise need.
	 *
	 * <p>The executor is virtual for the same reason {@code spring.threads.virtual.enabled}
	 * is set: under the {@code mock-fx} profile this application is its own provider, and
	 * the JDK client's default executor is a pool of platform threads sitting in the middle
	 * of that self-call.
	 */
	private static ClientHttpRequestFactory boundedByTimeouts(ExchangeRateSettings settings) {
		HttpClient httpClient = HttpClient.newBuilder()
				.connectTimeout(settings.connectTimeout())
				.executor(new VirtualThreadTaskExecutor("fx-client-"))
				.build();

		JdkClientHttpRequestFactory requests = new JdkClientHttpRequestFactory(httpClient);
		requests.setReadTimeout(settings.readTimeout());
		return requests;
	}
}

package hu.bankmonitor.payments.fx;

import hu.bankmonitor.payments.common.Currency;
import org.springframework.resilience.annotation.Retryable;
import org.springframework.stereotype.Component;
import org.springframework.web.client.ResourceAccessException;
import org.springframework.web.client.HttpServerErrorException;
import org.springframework.web.client.RestClient;

/**
 * One request to the Exchange Rate provider, asked again when the answer was the provider
 * having a bad moment.
 *
 * <p>This is the whole of the retry policy, and it is a separate bean from
 * {@link HttpExchangeRateProvider} for a reason that is structural rather than tidy:
 * {@code @Retryable} is proxy-based, so a call this class made to its own method would
 * bypass the proxy and never retry. The interception has to happen on a boundary between
 * two beans, which puts the mapping of the provider's failures onto ours in the caller.
 *
 * <p>{@code includes} names the two failures worth asking again about — the provider
 * answering {@code 5xx}, and the connection timing out or breaking, which reaches us as
 * {@link ResourceAccessException}. Everything else, {@code 4xx} above all, propagates from
 * the first attempt. A deterministic refusal repeated three times is three refusals and
 * one lie about how hard we tried.
 */
@Component
class RetriedQuotes {

	private static final String RATES_PATH = "/fx/rates";

	private final RestClient provider;

	RetriedQuotes(RestClient exchangeRateClient) {
		this.provider = exchangeRateClient;
	}

	/**
	 * @throws HttpServerErrorException if the provider failed every attempt
	 * @throws ResourceAccessException if the connection failed or timed out every attempt
	 * @throws org.springframework.web.client.HttpClientErrorException if the provider
	 *         refused the request, on the first attempt and without a second
	 */
	@Retryable(
			includes = { HttpServerErrorException.class, ResourceAccessException.class },
			maxRetriesString = ExchangeRateSettings.MAX_RETRIES,
			delayString = ExchangeRateSettings.RETRY_DELAY,
			multiplier = 2.0)
	ProviderQuote forPair(Currency base, Currency quote) {
		return provider.get()
				.uri(builder -> builder.path(RATES_PATH)
						.queryParam("base", base.name())
						.queryParam("quote", quote.name())
						.build())
				.retrieve()
				.body(ProviderQuote.class);
	}
}

