104		 */
105		@Test
106		@DisplayName("A provider that never answers becomes one failure naming what was tried")
107		void exhaustedRetriesBecomeADistinctFailure() {
108			provider.expect(times(3), requestTo(RATES)).andExpect(method(HttpMethod.GET))
109					.andRespond(withStatus(HttpStatus.SERVICE_UNAVAILABLE));
110	
111			assertThatExceptionOfType(ExchangeRateUnavailableException.class)
112					.isThrownBy(() -> rates.exchangeRateFor(Currency.EUR, Currency.HUF))
113					.satisfies(failure -> {
114						assertThat(failure.getAttempts()).isEqualTo(3);
115						assertThat(failure.getBase()).isEqualTo(Currency.EUR);
116						assertThat(failure.getQuote()).isEqualTo(Currency.HUF);
117					});
118	
119			assertThat(retries.gaveUp()).isTrue();
120			provider.verify();
121		}
