175							{"base":"USD","quote":"HUF","rate":361.40}""", MediaType.APPLICATION_JSON));
176	
177			assertThatThrownBy(() -> rates.exchangeRateFor(Currency.EUR, Currency.HUF))
178					.isInstanceOf(IllegalStateException.class)
179					.hasMessageContaining("USD");
180	
181			provider.verify();
182		}
183	
184		/**
185		 * Everything the port needs and nothing the application does not: the retry
186		 * post-processor, the two beans it sits between, and a {@link RestClient} pointed at a
187		 * server that only exists inside this test.
188		 */
189		@Configuration
190		@EnableResilientMethods
191		@EnableConfigurationProperties(ExchangeRateSettings.class)
192		@Import({ RetriedQuotes.class, HttpExchangeRateProvider.class, RecordedRetries.class })
193		static class ScriptedProvider {
194	
195			static final String BASE_URL = "http://exchange-rates.test";
196	
197			static final Instant FETCHED_AT = Instant.parse("2026-01-01T09:30:00Z");
198	
199			@Bean
